The utility of the `getNeighbors` function is obvious. The utility of the `getNeighbor` function is shown below:
```squirrel
// Objective:
// Get the first empty tile adjacent to myTile

// current workflow
local targetTile;
for (local i = 0; i < 6; i++)
{
	if (myTile.hasNextTile(i))
	{
		local nextTile = myTile.getNextTile(i);
		if (nextTile.IsEmpty)
		{
			targetTile = nextTile;
			break;
		}
	}
}

// new workflow:
local targetTile = ::MSU.Tile.getNeighbor(myTile, @(tile) tile.IsEmpty);
```

HashLink is the future of Haxe VMs, whereas Neko is unsupported and causes issues like #1307.

Unfortunately, this pull request currently doesn't work because the tools can't load lime.hdll. I assume this is because [the ndll-loading code is written for Neko](https://github.com/player-03/lime/blob/47f6b912cae748f6c842eec9e68a2677e95c350a/tools/CommandLineTools.hx#L474-L517):

```haxe
switch (System.hostPlatform)
{
	case WINDOWS:
		// var is64 = neko.Lib.load("std", "sys_is64", 0)();
		untyped $loader.path = $array(path + "Windows/", $loader.path);
		if (CFFI.enabled)
		{
			try
			{
				neko.Lib.load("lime", "lime_application_create", 0);
			}
			catch (e:Dynamic)
			{
				untyped $loader.path = $array(path + "Windows64/", $loader.path);
			}
		}

	case MAC:
		// if (System.hostArchitecture == X64) {

		untyped $loader.path = $array(path + "Mac64/", $loader.path);

	// } else {

	//	untyped $loader.path = $array (path + "Mac/", $loader.path);

	// }

	case LINUX:
		var arguments = Sys.args();
		var raspberryPi = false;

		for (argument in arguments)
		{
			if (argument == "-rpi") raspberryPi = true;
		}

		if (raspberryPi || System.hostArchitecture == ARMV6 || System.hostArchitecture == ARMV7)
		{
			untyped $loader.path = $array(path + "RPi/", $loader.path);
		}
		else if (System.hostArchitecture == X64)
		{
			untyped $loader.path = $array(path + "Linux64/", $loader.path);
		}
		else
		{
			untyped $loader.path = $array(path + "Linux/", $loader.path);
		}

	default:
}
```

